<?php require '../config/database.php'; require_once '../config/auth.php'; require_role('admin');
if(isset($_GET['toggle'])){ $id=(int)$_GET['toggle']; mysqli_query($conn,"UPDATE users SET status=IF(status='active','inactive','active') WHERE id=$id"); header('Location: members.php'); exit; }
$rows=mysqli_query($conn,"SELECT u.*,m.height_cm,m.weight_kg,m.goal FROM users u LEFT JOIN members m ON u.id=m.user_id WHERE u.role='member' ORDER BY u.id DESC"); ?>
<!DOCTYPE html><html><head><title>Members</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="layout"><?php include '_nav.php'; ?><main class="main"><div class="header"><h1>Member Management</h1><a class="btn" href="../register.php">Add Member</a></div><table class="table"><tr><th>Name</th><th>Email</th><th>Goal</th><th>Height</th><th>Weight</th><th>Status</th><th>Action</th></tr><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['goal'])?></td><td><?=$r['height_cm']?></td><td><?=$r['weight_kg']?></td><td><span class="badge <?=$r['status']=='active'?'':'danger'?>"><?=$r['status']?></span></td><td><a class="btn light" href="?toggle=<?=$r['id']?>">Toggle</a></td></tr><?php endwhile;?></table></main></div></body></html>
